// @pit: {"label": "Add pit CHANGELOG entry, commit locally, produce patch"}
async ({ shell: { exec }, workspace: { read, edit } }) => {
  const f = "/tmp/pit/CHANGELOG.md";
  const r = await read(f, { format: "raw" });
  const c = r.content.replace("## [Unreleased]\n", "## [Unreleased]\n\n### Fixed\n\n- On pi-durable hosts, shell output that arrives after the `typescript` call settled (its session failed, or the host aborted it) is dropped. Before, pi-durable's `Tool call … has settled` error escaped the command's stdout handler and crashed the host process, as in a pi-action run whose storage failed.\n");
  await edit(f, { revision: r.revision, changes: [{ kind: "replaceFile", content: c }] });
  const t = await exec(`cd /tmp/pit && for i in 1 2; do npx vitest run test/durable/settled-output.test.ts 2>&1 | sed 's/\\x1b\\[[0-9;]*m//g' | grep -E 'Tests '; done; npx --no-install oxfmt --check CHANGELOG.md src test >/dev/null && echo fmt-ok; git add -A && git -c user.name=pi-action-agent -c user.email=pi@noreply commit -q -m "fix(durable): drop shell output that arrives after the call settled

When a pi-durable session failed while a program's command still
printed, the output left in the pipe reached api.output after the call
settled. pi-durable threw 'Tool call ... has settled' from the child's
stdout handler, and the host process (pi-action) crashed.

Seen in https://github.com/cv/pi-action/actions/runs/43520110827." && git format-patch -1 --stdout > /tmp/pit-fix.patch; wc -l /tmp/pit-fix.patch`, { timeoutMs: 120000 });
  const p = await read("/tmp/pit-fix.patch", { format: "raw" });
  return t.stdout + t.stderr + "\n" + p.content;
}
